sys_ui_page.client_script:
var smartAttendShifts = [];


window.addEventListener(
    'load',
    function() {

        loadShiftManagement();

    }
);


// =============================================================
// HEADERS
// =============================================================
function buildHeaders(
    includeJson
) {

    var headers = {};


    if (includeJson) {

        headers[
            'Content-Type'
        ] =
            'application/json';

    }


    if (
        typeof window.g_ck !==
            'undefined' &&
        window.g_ck
    ) {

        headers[
            'X-UserToken'
        ] =
            window.g_ck;

    }


    return headers;
}


// =============================================================
// LOAD DATA
// =============================================================
function loadShiftManagement() {

    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/shift-management',
        {
            method: 'GET',

            credentials:
                'same-origin',

            headers:
                buildHeaders(false)
        }
    )

    .then(function(response) {

        return response.json();

    })

    .then(function(data) {

        if (
            !data.result ||
            !data.result.success
        ) {

            throw new Error(
                'Unable to load shift management.'
            );

        }


        renderShiftManagement(
            data.result
        );

    })

    .catch(function(error) {

        showMessage(
            error.message,
            false
        );


        document.getElementById(
            'loadingBox'
        ).textContent =
            'Unable to load shift management.';

    });

}


// =============================================================
// RENDER PAGE
// =============================================================
function renderShiftManagement(
    data
) {

    smartAttendShifts =
        data.shifts || [];


    document.getElementById(
        'loadingBox'
    ).style.display =
        'none';


    document.getElementById(
        'mainContent'
    ).style.display =
        'block';


    document.getElementById(
        'managerCard'
    ).style.display =
        'block';


    document.getElementById(
        'managerName'
    ).textContent =
        data.manager ||
        'Manager';


    renderShifts(
        smartAttendShifts
    );


    renderEmployees(
        data.employees || []
    );

}


// =============================================================
// RENDER SHIFTS
// =============================================================
function renderShifts(
    shifts
) {

    var container =
        document.getElementById(
            'shiftContainer'
        );


    if (
        !shifts ||
        shifts.length === 0
    ) {

        container.innerHTML =
            '<div class="shift-card">' +
                'No active shifts available.' +
            '</div>';

        return;

    }


    var html = '';


    for (
        var i = 0;
        i < shifts.length;
        i++
    ) {

        var shift =
            shifts[i];


        html +=

            '<div class="shift-card">' +

                '<div class="shift-name">' +

                    escapeHtml(
                        shift.shift_name
                    ) +

                '</div>' +

                '<div class="shift-number">' +

                    escapeHtml(
                        shift.number || ''
                    ) +

                '</div>' +

                '<div class="shift-time">' +

                    escapeHtml(
                        shift.start_time
                    ) +

                    ' – ' +

                    escapeHtml(
                        shift.end_time
                    ) +

                '</div>' +

                '<div class="shift-details">' +

                    miniBox(
                        'Grace',
                        shift.grace_minutes +
                        ' min'
                    ) +

                    miniBox(
                        'Full Day',
                        shift.full_day_minutes +
                        ' min'
                    ) +

                    miniBox(
                        'Half Day',
                        shift.half_day_minutes +
                        ' min'
                    ) +

                '</div>' +

            '</div>';

    }


    container.innerHTML =
        html;

}


// =============================================================
// RENDER EMPLOYEES
// =============================================================
function renderEmployees(
    employees
) {

    var container =
        document.getElementById(
            'employeeContainer'
        );


    if (
        !employees ||
        employees.length === 0
    ) {

        container.innerHTML =
            '<div class="employee-card">' +
                'No employees are assigned to you.' +
            '</div>';

        return;

    }


    var html = '';


    for (
        var i = 0;
        i < employees.length;
        i++
    ) {

        var employee =
            employees[i];


        html +=

            '<div class="employee-card">' +

                '<div class="employee-header">' +

                    '<div>' +

                        '<div class="employee-name">' +

                            escapeHtml(
                                employee.employee
                            ) +

                        '</div>' +

                        '<div class="employee-meta">' +

                            escapeHtml(
                                employee.employee_code ||
                                'No Employee Code'
                            ) +

                            ' • ' +

                            escapeHtml(
                                employee.department ||
                                'No Department'
                            ) +

                        '</div>' +

                    '</div>' +


                    '<div class="current-shift">' +

                        escapeHtml(
                            employee.current_shift ||
                            'Not Assigned'
                        ) +

                    '</div>' +

                '</div>' +


                '<div class="assignment-row">' +

                    '<select id="shift_' +
                        escapeHtml(
                            employee.profile_id
                        ) +
                    '">' +

                        buildShiftOptions(
                            employee.current_shift_id
                        ) +

                    '</select>' +


                    '<button onclick="assignShift(\'' +
                        escapeJs(
                            employee.profile_id
                        ) +
                    '\');">' +

                        'Assign Shift' +

                    '</button>' +

                '</div>' +

            '</div>';

    }


    container.innerHTML =
        html;

}


// =============================================================
// SHIFT OPTIONS
// =============================================================
function buildShiftOptions(
    selectedShift
) {

    var html = '';


    for (
        var i = 0;
        i < smartAttendShifts.length;
        i++
    ) {

        var shift =
            smartAttendShifts[i];


        var selected =
            shift.shift_id ===
            selectedShift
                ? ' selected="selected"'
                : '';


        html +=

            '<option value="' +
                escapeHtml(
                    shift.shift_id
                ) +
            '"' +
            selected +
            '>' +

                escapeHtml(
                    shift.shift_name +
                    ' (' +
                    shift.start_time +
                    ' - ' +
                    shift.end_time +
                    ')'
                ) +

            '</option>';

    }


    return html;

}


// =============================================================
// CREATE SHIFT
// =============================================================
function createShift() {

    var name =
        document.getElementById(
            'shiftName'
        ).value.trim();


    var start =
        document.getElementById(
            'startTime'
        ).value;


    var end =
        document.getElementById(
            'endTime'
        ).value;


    var grace =
        parseInt(
            document.getElementById(
                'graceMinutes'
            ).value,
            10
        );


    var fullDay =
        parseInt(
            document.getElementById(
                'fullDayMinutes'
            ).value,
            10
        );


    var halfDay =
        parseInt(
            document.getElementById(
                'halfDayMinutes'
            ).value,
            10
        );


    var description =
        document.getElementById(
            'shiftDescription'
        ).value.trim();


    if (
        !name ||
        !start ||
        !end
    ) {

        showMessage(
            'Shift name, start time and end time are required.',
            false
        );

        return;

    }


    var startMinutes =
        timeToMinutes(
            start
        );


    var endMinutes =
        timeToMinutes(
            end
        );


    var button =
        document.getElementById(
            'createShiftButton'
        );


    button.disabled =
        true;


    button.textContent =
        'Creating...';


    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/create-shift',
        {
            method: 'POST',

            credentials:
                'same-origin',

            headers:
                buildHeaders(true),

            body:
                JSON.stringify({

                    shift_name:
                        name,

                    start_minutes:
                        startMinutes,

                    end_minutes:
                        endMinutes,

                    grace_minutes:
                        grace,

                    full_day_minutes:
                        fullDay,

                    half_day_minutes:
                        halfDay,

                    description:
                        description,

                    active:
                        true

                })
        }
    )

    .then(function(response) {

        return response.json();

    })

    .then(function(data) {

        var result =
            data.result;


        if (
            !result ||
            !result.success
        ) {

            throw new Error(
                result &&
                result.message
                    ? result.message
                    : 'Unable to create shift.'
            );

        }


        showMessage(
            result.message,
            true
        );


        clearShiftForm();


        loadShiftManagement();

    })

    .catch(function(error) {

        showMessage(
            error.message,
            false
        );

    })

    .then(function() {

        button.disabled =
            false;


        button.textContent =
            'Create Shift';

    });

}


// =============================================================
// ASSIGN SHIFT
// =============================================================
function assignShift(
    profileId
) {

    var select =
        document.getElementById(
            'shift_' +
            profileId
        );


    if (!select) {

        return;

    }


    var shiftId =
        select.value;


    if (!shiftId) {

        showMessage(
            'Select a shift first.',
            false
        );

        return;

    }


    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/assign-shift',
        {
            method: 'POST',

            credentials:
                'same-origin',

            headers:
                buildHeaders(true),

            body:
                JSON.stringify({

                    profile_id:
                        profileId,

                    shift_id:
                        shiftId

                })
        }
    )

    .then(function(response) {

        return response.json();

    })

    .then(function(data) {

        var result =
            data.result;


        if (
            !result ||
            !result.success
        ) {

            throw new Error(
                result &&
                result.message
                    ? result.message
                    : 'Unable to assign shift.'
            );

        }


        showMessage(
            result.employee.employee +
            ' assigned to ' +
            result.employee.current_shift +
            '.',
            true
        );


        loadShiftManagement();

    })

    .catch(function(error) {

        showMessage(
            error.message,
            false
        );

    });

}


// =============================================================
// HELPERS
// =============================================================
function timeToMinutes(
    value
) {

    var parts =
        value.split(':');


    return (
        parseInt(
            parts[0],
            10
        ) *
        60
    ) +
    parseInt(
        parts[1],
        10
    );

}


function clearShiftForm() {

    document.getElementById(
        'shiftName'
    ).value = '';


    document.getElementById(
        'startTime'
    ).value = '';


    document.getElementById(
        'endTime'
    ).value = '';


    document.getElementById(
        'graceMinutes'
    ).value = '10';


    document.getElementById(
        'fullDayMinutes'
    ).value = '480';


    document.getElementById(
        'halfDayMinutes'
    ).value = '240';


    document.getElementById(
        'shiftDescription'
    ).value = '';

}


function miniBox(
    label,
    value
) {

    return (

        '<div class="mini-box">' +

            '<div class="mini-label">' +
                escapeHtml(
                    label
                ) +
            '</div>' +

            '<div class="mini-value">' +
                escapeHtml(
                    String(value)
                ) +
            '</div>' +

        '</div>'

    );

}


function showMessage(
    message,
    success
) {

    var box =
        document.getElementById(
            'messageBox'
        );


    box.className =
        success
            ? 'message message-success'
            : 'message message-error';


    box.textContent =
        message;


    window.scrollTo(
        0,
        0
    );

}


function escapeHtml(
    value
) {

    return String(
        value === null ||
        value === undefined
            ? ''
            : value
    )

    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

}


function escapeJs(
    value
) {

    return String(value)
        .replace(
            /\\/g,
            '\\\\'
        )
        .replace(
            /'/g,
            "\\'"
        );

}
